export function ContentArea({
  heading = "{{heading}}",
  density = "{{density}}",
  accent = "{{accent}}",
  scroll = {{scroll}},
}) {
  const compact = density === "compact";
  return (
    <div style={{ display: "flex", fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430", border: "1px solid #24143022" }}>
      <div style={{ flex: "none", width: 56, background: "#241430", color: "#FAF7F2cc", fontSize: 12, textAlign: "center", paddingTop: 14 }}>Nav</div>
      <main style={{
        flex: 1, minWidth: 0, background: "#FAF7F2", borderTop: `3px solid ${accent}`,
        padding: compact ? "10px 14px" : 20, fontSize: compact ? 13 : 14,
        height: scroll ? 150 : "auto", overflowY: scroll ? "auto" : "visible",
      }}>
        <h3 style={{ margin: "0 0 10px" }}>{heading}</h3>
        <p style={{ margin: "0 0 8px", color: "#241430cc" }}>The main content region is the primary task area of the page, distinct from chrome like navigation.</p>
        <p style={{ margin: "0 0 8px", color: "#241430cc" }}>It usually scrolls independently of surrounding fixed regions.</p>
        <p style={{ margin: "0 0 8px", color: "#241430cc" }}>A third paragraph makes that scrolling behaviour visible when the height is constrained.</p>
        <p style={{ margin: 0, color: "#241430cc" }}>And a fourth, so there is genuinely more to scroll through.</p>
      </main>
    </div>
  );
}
